import{_ as t,o,c as a,a3 as d}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"Command Line Overview","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Command Line Overview | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/cli/overview"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/cli/overview"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/cli/overview"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/cli/overview"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/cli/overview"}]]},"headers":[],"relativePath":"clice/cli/overview.md","filePath":"en/clice/cli/overview.md","lastUpdated":1793393027000}'),r={name:"clice/cli/overview.md"};function c(i,e,n,s,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="command-line-overview" tabindex="-1">Command Line Overview <a class="header-anchor" href="#command-line-overview" aria-label="Permalink to &quot;Command Line Overview&quot;">​</a></h1><p>clice is one binary. Editors launch <code>clice serve</code> and talk to it over LSP; the other subcommands drive the same engine from a terminal, sharing its compilation database handling, caches and index.</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td><code>serve</code></td><td>Start the language server. Editors do this for you, see the editor setup.</td><td><a href="./../guide/editors">editors</a></td></tr><tr><td><code>lint</code></td><td>Run clang-tidy over every translation unit with a worker pool.</td><td><a href="./lint">lint</a></td></tr><tr><td><code>index</code></td><td>Index a project ahead of time so the server starts warm.</td><td><a href="./">index</a></td></tr><tr><td><code>format</code></td><td>Format the project&#39;s files with clang-format.</td><td><a href="./format">format</a></td></tr><tr><td><code>inspect</code></td><td>Run one feature on a source file and print the raw result as JSON.</td><td></td></tr><tr><td><code>command</code></td><td>Show the commands a file compiles with, and convert compile commands for other tools.</td><td><a href="./command">command</a></td></tr><tr><td><code>query</code></td><td>Ask the persisted index about symbols, references, call graphs and files.</td><td><a href="./query">query</a></td></tr><tr><td><code>refactor</code></td><td>Rename a symbol across the project from the persisted index.</td><td><a href="./refactor">refactor</a></td></tr><tr><td><code>analyze</code></td><td>Report facts for refactoring, such as module dependencies and cycles.</td><td><a href="./analyze">analyze</a></td></tr><tr><td><code>modularize</code></td><td>Wrap third-party libraries as C++20 modules, rewrite the program into module units.</td><td><a href="./modularize">modularize</a></td></tr><tr><td><code>scan</code></td><td>Scan the include and module dependencies of the build, and time the scan.</td><td><a href="./scan">scan</a></td></tr></tbody></table><p><code>inspect</code> works today but has no page yet; its operations and options are documented by <code>clice inspect --help</code>.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><p>Every subcommand takes its arguments the same way:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>clice &lt;command&gt; [&lt;operation&gt;] [&lt;target&gt;...] [--option...]</span></span></code></pre></div><ul><li>A command that does several things names the one to do by a word after it: <code>clice query references</code>, <code>clice index stats</code>, <code>clice analyze modules edge</code>. A command whose own job comes first runs it when no word follows: <code>clice index</code> indexes, <code>clice analyze modules</code> gives the overview, <code>clice command &lt;file&gt;</code> shows the file&#39;s commands. <code>--help</code> after any command or operation lists what it takes.</li><li>The target, the symbol or file an operation is about, follows the operation: <code>clice query references &quot;shapes::Circle::area&quot;</code>, <code>clice query document-symbols src/main.cpp</code>. A symbol is named by a <a href="./query#locators">locator</a> wherever one is taken; a file by its path, relative to the current directory or absolute, as is every other path on the command line, such as a partition or an output directory.</li><li>Options come after the operation. An option takes several values by being repeated: <code>--scope &#39;src/**&#39; --scope &#39;include/**&#39;</code>.</li><li><code>--workspace &lt;dir&gt;</code> names the project root; without it a command works on the project above the current directory, as git finds its repository: the nearest directory holding a <code>clice.toml</code>, a <code>.clice/config.toml</code> or a <code>compile_commands.json</code>, directly or in its <code>build/</code> directory, else the current directory itself (<code>inspect</code> looks up from the file, as the editor does). A configuration the command cannot take — a file that does not parse, a value of the wrong type, an option it cannot honor — fails it with exit code 2, each problem named with its place in the file; <code>--configuration &lt;tag&gt;</code> pins the build configuration over the selection persisted from the editor (see <a href="./../guide/configuration#switching-configurations">switching configurations</a>); <code>-j</code>, <code>--jobs &lt;n&gt;</code> is how many units or files <code>index</code>, <code>lint</code> and <code>format</code> work on at once; <code>--log-level</code> sets what is logged to stderr, warnings and errors by default (<code>serve</code>, whose stderr an editor shows, from <code>info</code>); the session logs of <code>serve</code>, <code>index</code> and <code>lint</code> keep <code>info</code> whatever it is.</li></ul>',8)])])}const f=t(r,[["render",c]]);export{p as __pageData,f as default};
